CREATE   PROCEDURE SP_PC_CD_RegistrarComprobante    -- Add the parameters for the stored procedure here    @IdProveedor INT,                   @IdContrato INT,                   @IdUsuario INT,               @FolioComprobante NVARCHAR(MAX),	@IdFormaPago INT,	@FechaPago DATE,	@IdMoneda INT,	@CvTipoDocFacturacion INT,	@IdProveedorExportador INT,	@HashSHA256 NVARCHAR(300)  ASBEGIN    -- SET NOCOUNT ON added to prevent extra result sets from    -- interfering with SELECT statements.    SET NOCOUNT ON;		INSERT INTO dbo.FI_PedimentoComprobante	(	    IdContrato,  	    FolioComprobante,	    FechaPago,	   	    IdSubcontratistaImportador,	 	    IdSubcontratistaExportador,	    IdFormaPago,	    IdMoneda,	    CvTipoDocFacturacion,	   	    CreadoPor,	    CreadoEn,	    IsEliminado,	    IsActivo,	    IsBorrador,	    TipoOrigen,		HashSHA256	)	VALUES	(   @IdContrato,         -- IdContrato - int	    	    @FolioComprobante,       -- FolioComprobante - nvarchar(50)	    @FechaPago, -- FechaPago - date	   	    @IdProveedor,         -- IdSubcontratistaImportador - int	    	    @IdProveedorExportador,         -- IdSubcontratistaExportador - int	    @IdFormaPago,         -- IdFormaPago - int	    @IdMoneda,         -- IdMoneda - int	    @CvTipoDocFacturacion,         -- CvTipoDocFacturacion - int  		@IdUsuario,         -- CreadoPor - int	    GETDATE(), -- CreadoEn - datetime	    0,      -- IsEliminado - bit	    1,      -- IsActivo - bit	    1,      -- IsBorrador - bit	    'P_CECD',  -- TipoOrigen - NVARCHAR(50) --> PROCURA COMPROBANTE EXTRANJERO COMPRA DIRECTA 		@HashSHA256	    )						/*GENERAR PEDIDO GENERAL AL COMPROBANTE EXTRANJERO*/		DECLARE @IdPedimentoComprobante INT = (SELECT @@IDENTITY)		DECLARE @IdPedidoGeneral INT		DECLARE @FECHA_ACTUAL DATETIME =(SELECT GETDATE())		EXEC dbo.SP_MM_GenerarIdPedidoGeneral @IdTipoPedido = 7,                     -- int 7 = Comprobante extranjero --> MM_TipoPedido		                                    @IdPrimaryKey =@IdPedimentoComprobante,          -- int		                                    @CreadoPor = @IdUsuario,		     -- int		                                    @CreadoEl = @FECHA_ACTUAL,               -- datetime		                                    @IdProveedorActual = @IdProveedor , -- int		                                    @IdPedidoGeneral = @IdPedidoGeneral OUTPUT -- int					UPDATE 		dbo.FI_PedimentoComprobante 		SET IdPedidoGeneral=@IdPedidoGeneral		WHERE IdPedimentoComprobante= @IdPedimentoComprobante	 SELECT @IdPedimentoComprobante, @IdPedidoGeneralEND;